class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        marked = [0] * n
        earliest_second = 1
        for s in range(m):
            if nums[changeIndices[s]-1] > 0:
                nums[changeIndices[s]-1] -= 1
            else:
                marked[changeIndices[s]-1] = 1
            if all(marked):
                return earliest_second
            earliest_second += 1
        return -1
```

